window.MGProseData("28ce710f6989f758d22aa3d815fe32d947e0c260d1ca8af146c8cbb205f48512",{"html":"\u003cp>\u003cstrong>S1\u003c/strong>\u003c/p>\n\u003cp>记 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q:Y\\to Y/A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的收缩\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>h\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nh:A\\times I\\to A,\\qquad h(a,0)=a,\\quad h(a,1)=a_0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于子复形包含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003cmo>↪\u003c/mo>\u003cmi>Y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\\hookrightarrow Y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是上纤维化，具有同伦延拓性质，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>h\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>Y\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{id}_Y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 延拓为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>H\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>Y\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>H\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmrow>\u003cmi>A\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi>I\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>h\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nH:Y\\times I\\to Y,\\qquad H_0=\\operatorname{id}_Y,\\quad H|_{A\\times I}=h.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H_1(A)=\\{a_0\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 唯一分解为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>f\u003c/mi>\u003cmi>q\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>f\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nH_1=fq,\\qquad f:Y/A\\to Y.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n于是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmi>q\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>Y\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">fq\\simeq\\operatorname{id}_Y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>另一方面，对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，都有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⊆\u003c/mo>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H_t(A)\\subseteq A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">qH_t\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在整个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上取同一值。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmi>H\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">qH\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 下降为同伦\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmo>:\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>×\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\overline H:(Y/A)\\times I\\to Y/A.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这里联合连续性也有保证：有限 CW 复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 紧且 Hausdorff，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 闭，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Y/A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是紧 Hausdorff 空间；于是连续满射\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>×\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>I\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>⟶\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>×\u003c/mo>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nq\\times\\operatorname{id}_I:Y\\times I\\longrightarrow (Y/A)\\times I\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n是商映射。因而上述下降映射连续。\u003c/p>\n\u003cp>其两端满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>q\u003c/mi>\u003cmi>f\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\overline H_0=\\operatorname{id}_{Y/A},\\qquad \\overline H_1=qf.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 互为同伦逆。关键在于延拓时指定了 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>H\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmrow>\u003cmi>A\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi>I\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>h\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H|_{A\\times I}=h\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，保证整个同伦都把 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 映入 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003chr>\n\u003cp>\u003cstrong>S2\u003c/strong>\u003c/p>\n\u003cp>先说明所用的映射锥事实。对于同伦映射 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>g\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f,g:L\\to D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其映射锥\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>D\u003c/mi>\u003cmsub>\u003cmo>∪\u003c/mo>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmi>C\u003c/mi>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>g\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>D\u003c/mi>\u003cmsub>\u003cmo>∪\u003c/mo>\u003cmi>g\u003c/mi>\u003c/msub>\u003cmi>C\u003c/mi>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nC_f=D\\cup_f CL,\\qquad C_g=D\\cup_g CL\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n同伦等价。\u003c/p>\n\u003cp>事实上，设 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F:L\\times I\\to D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 从 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 同伦到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>g\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 表示锥底、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 表示锥尖。定义 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>g\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T_F:C_f\\to C_g\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上为恒等，在锥上为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>t\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo>≤\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmn>1.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nT_F([\\ell,t])=\n\\begin{cases}\nF(\\ell,2t),\u0026amp;0\\le t\\le \\frac12,\\\\\n[\\ell,2t-1],\u0026amp;\\frac12\\le t\\le1.\n\\end{cases}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n各拼接处相容，故这是连续映射。反向同伦给出反向映射。两个复合在锥坐标上都表现为：先沿同伦往返一次，再进入原锥。往返段经重新参数化后，可用\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">(\u003c/mo>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>r\u003c/mi>\u003cmi>min\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>s\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>r\u003c/mi>\u003cmo>:\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>⟶\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nF\\bigl(\\ell,r\\min\\{2s,2-2s\\}\\bigr),\\qquad r:1\\longrightarrow0,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n缩成常值段，再缩短这一常值段，便得到恒等映射。这些同伦均固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，证明了该事实。\u003c/p>\n\u003cp>现在令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo>↪\u003c/mo>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">i:L\\hookrightarrow D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。按假设，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>i\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 同伦于常值映射 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>c\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">c_{d_0}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，于是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≃\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmsub>\u003cmi>c\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/msub>\u003c/msub>\u003cmo>≅\u003c/mo>\u003cmi>D\u003c/mi>\u003cmsub>\u003cmo>∨\u003c/mo>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>C\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>L\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nY=C_i\\simeq C_{c_{d_0}}\n\\cong D\\vee_{d_0}(CL/L).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n而\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>L\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nCL/L\\cong \\Sigma L,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因为锥底被压成一个悬挂极点，锥尖是另一个极点。因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi>D\u003c/mi>\u003cmo>∨\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{Y\\simeq D\\vee\\Sigma L.}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>楔点在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中取零伦的常值点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">d_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中取由锥底压成的极点。由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 路径连通，可以在零伦后接上一条路径，把 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">d_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 改为任意指定点；特别可以选一个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-胞腔，使楔和具有通常的 CW 结构。\u003c/p>\n\u003chr>\n\u003cp>\u003cstrong>S3\u003c/strong>\u003c/p>\n\u003cp>先记录一个也用于后文的删点事实。对有限单纯复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的顶点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>σ\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi>K\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmi>σ\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nD=\\{\\sigma\\in K:v\\notin\\sigma\\}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n为删点子复形。若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\\ne v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的重心坐标为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>t\u003c/mi>\u003cmi>u\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(t_u)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>t\u003c/mi>\u003cmi>v\u003c/mi>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t_v\u0026lt;1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，可定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>v\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmsub>\u003cmi>t\u003c/mi>\u003cmi>u\u003c/mi>\u003c/msub>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>t\u003c/mi>\u003cmi>v\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmtext> \u003c/mtext>\u003cmi>u\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nr(x)=\\sum_{u\\ne v}\\frac{t_u}{1-t_v}\\,u.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n它落在包含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的单形去掉 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 所得的面内。直线同伦\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>R\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nR_s(x)=(1-s)x+sr(x)\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n始终留在同一单形内且不经过 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|D|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。所以\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmtext> 强形变收缩到 \u003c/mtext>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(1)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n|K|\\setminus\\{v\\}\\ \\text{强形变收缩到}\\ |D|.\n\\tag{1}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>现在取两个新顶点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>w\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v,w\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmo>∪\u003c/mo>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nK=(v*L)\\cup_L(w*L).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n即取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的单纯悬挂，因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|K|\\cong\\Sigma|L|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n任选 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的顶点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为边 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{v,a\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及其所有面。\u003c/p>\n\u003cp>删点子复形为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D=w*L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，它非空且可缩。由 (1)，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|K|\\setminus\\{v\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非空可缩。另一方面，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>B\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|B|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 和 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>B\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|B|\\setminus\\{v\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都可沿该边收缩到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>B\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>↪\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>B\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|B|\\setminus\\{v\\}\\hookrightarrow |B|\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n是同伦等价。\u003c/p>\n\u003cp>由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmsup>\u003cmrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmi mathvariant=\"double-struck\">P\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|L|\\cong\\mathbb {RP}^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其约化有理同调全零。悬挂同调移位给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Q\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"2em\"/>\u003cmtext>对所有 \u003c/mtext>\u003cmi>n\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widetilde H_n(|K|;\\mathbb Q)=0\\qquad\\text{对所有 }n.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n但整数系数下\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmi mathvariant=\"double-struck\">P\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widetilde H_2(|K|;\\mathbb Z)\n\\cong \\widetilde H_1(\\mathbb {RP}^2;\\mathbb Z)\n\\cong\\mathbb Z/2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|K|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 不可缩，满足全部要求。\u003c/p>\n\u003chr>\n\u003cp>\u003cstrong>S4\u003c/strong>\u003c/p>\n\u003cp>结论是：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmtext>可能的同伦类型，恰为所有非空有限单纯复形的非约化悬挂。\u003c/mtext>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(2)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\text{可能的同伦类型，恰为所有非空有限单纯复形的非约化悬挂。}}\n\\tag{2}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为上述删点子复形，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>τ\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi>K\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmi>τ\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>τ\u003c/mi>\u003cmo>∪\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmi>K\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nL=\\operatorname{lk}_K(v)\n=\\{\\tau\\in K:v\\notin\\tau,\\ \\tau\\cup\\{v\\}\\in K\\}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n以下说链结非空，均指 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|L|\\ne\\varnothing\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，即链结含有顶点。单纯复形有分解\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>D\u003c/mi>\u003cmsub>\u003cmo>∪\u003c/mo>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(3)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nK=D\\cup_L(v*L).\n\\tag{3}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>由 (1)，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>O\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">O\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 强形变收缩到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|D|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|D|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非空可缩。\u003c/p>\n\u003cp>条件 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 保证 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|L|\\ne\\varnothing\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。否则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 不属于任何边，是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的孤立点，因而也是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的一个单独分支。映射\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>O\u003c/mi>\u003cmo>∩\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>⟶\u003c/mo>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nO\\cap C=C\\setminus\\{v\\}\\longrightarrow C\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n便遗漏了该分支，不可能在路径分支集合上诱导双射，与其为同伦等价矛盾。\u003c/p>\n\u003cp>由 S1，可缩子复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|D|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的商映射是同伦等价。再由 (3)，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi>X\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>v\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(4)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nX\\simeq X/|D|\n\\cong |v*L|/|L|\n\\cong\\Sigma|L|.\n\\tag{4}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这里商空间的同胚来自两个闭子复形的拼接；锥底压成一个极点，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是另一个极点。这证明所有满足条件的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都在 (2) 中。\u003c/p>\n\u003cp>反过来，给定任意非空有限单纯复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmo>∪\u003c/mo>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nK=(v*M)\\cup_M(w*M),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n并取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的任一顶点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为边 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{v,a\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及其面。S3 的验证原样适用：删点空间强形变收缩到锥 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>w\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">w*M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，而边及其删去端点后的空间均收缩到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。故全部原条件成立，且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>M\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|K|\\cong\\Sigma|M|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此 (2) 中每一种类型均有实现。\u003c/p>\n\u003cp>可缩性的局部判据为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi>X\u003c/mi>\u003cmtext> 可缩\u003c/mtext>\u003cmspace width=\"1em\"/>\u003cmo>⟺\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmtext>对所有 \u003c/mtext>\u003cmi>j\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(5)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\nX\\text{ 可缩}\n\\quad\\Longleftrightarrow\\quad\n\\widetilde H_j(\\operatorname{lk}_K(v);\\mathbb Z)=0\n\\quad\\text{对所有 }j\\ge0.\n}\n\\tag{5}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>必要性由 (4) 和悬挂同调移位立即得到。证明充分性时，链结的约化整数同调全零，特别是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\widetilde H_0(L;\\mathbb Z)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故有限复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|L|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 路径连通。悬挂可由两个可缩的开锥邻域覆盖，其交集同伦等价于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|L|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因此 van Kampen 定理适用，给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\pi_1(\\Sigma|L|)=0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n悬挂同调移位又说明 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma|L|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的约化整数同调全零。\u003c/p>\n\u003cp>单连通、整数无约化同调的 CW 复形可缩：若存在非零同伦群，取最小的相应次数，Hurewicz 定理将其同构到同次数的非零同调群，矛盾；于是到一点的映射是弱同伦等价，再由 Whitehead 定理是同伦等价。这里 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma|L|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是有限 CW 复形，满足适用条件。这证明了 (5)。\u003c/p>\n\u003cp>最后，(5) 确实只需题目指定的有限局部数据即可检验。对每个含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的单形删去 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，便得到链结的全部单形及面关联。给其他顶点排序，构造增广整数单纯链复形\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo>⋯\u003c/mo>\u003cmo>⟶\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⟶\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmover>\u003cmo stretchy=\"true\" minsize=\"3.0em\">→\u003c/mo>\u003cmpadded width=\"+0.6em\" lspace=\"0.3em\">\u003cmi>ϵ\u003c/mi>\u003c/mpadded>\u003c/mover>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo>⟶\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>ϵ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>1.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\cdots\\longrightarrow C_1(L;\\mathbb Z)\n\\longrightarrow C_0(L;\\mathbb Z)\n\\xrightarrow{\\epsilon}\\mathbb Z\\longrightarrow0,\n\\qquad \\epsilon([a])=1.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>q\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_q(L;\\mathbb Z)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的基与含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(q+1)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-单形对应，边界仅涉及删去非 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 顶点的面。判据就是此增广链复形处处正合。利用整数矩阵的 Smith 标准形计算核、像并检验相等，是有限算法，无须读取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的其他单形。\u003c/p>\n\u003chr>\n\u003cp>\u003cstrong>S5\u003c/strong>\u003c/p>\n\u003cp>不一定。去掉 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 后，恰好新增一种同伦类型：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{S^0.}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>仍用删点子复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 和链结 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由 (1)，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|D|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非空可缩。\u003c/p>\n\u003cul>\n\u003cli>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|L|\\ne\\varnothing\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，S4 中的商论证仍适用，得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|K|\\simeq\\Sigma|L|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n此时也总能补选一条以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为端点的边作为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003cli>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|L|=\\varnothing\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 孤立，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>⊔\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>≃\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|K|=|D|\\sqcup\\{v\\}\\simeq S^0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/li>\n\u003c/ul>\n\u003cp>取只有两个孤立顶点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>w\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v,w\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的有限复形即可实现后一种情况：删去 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 后是单点，但整体为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">S^0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。非空空间的非约化悬挂总是路径连通，所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">S^0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 不可能同伦等价于题目所说的悬挂。\u003c/p>\n\u003chr>\n\u003cp>\u003cstrong>S6\u003c/strong>\u003c/p>\n\u003cp>不必。取有限单纯复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L_1,L_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，分别实现\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>W\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nT^2,\\qquad W=S^1\\vee S^1\\vee S^2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n二环面具有有限三角剖分；\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>W\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">W\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可由两个三角形边界和一个四面体边界，在各自一个顶点处相交构造为有限单纯复形。\u003c/p>\n\u003cp>它们不同伦等价，因为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>W\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\pi_1(T^2)\\cong\\mathbb Z^2,\\qquad\n\\pi_1(W)\\cong F_2,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n前者交换，后者不交换。下面验证它们的悬挂同伦等价。\u003c/p>\n\u003cp>记约化悬挂为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma_r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对带 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-胞腔基点的有限 CW 复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Z\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Z\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，非约化悬挂中基点扫出的弧是可缩子复形，压掉此弧得到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmi>Z\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma_r Z\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由 S1，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>Z\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmi>Z\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(6)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\Sigma Z\\simeq\\Sigma_r Z.\n\\tag{6}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>二环面的通常 CW 分解为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmo>∪\u003c/mo>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmsup>\u003cmi>D\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nT^2=(S^1\\vee S^1)\\cup_f D^2,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo>:\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>→\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f:S^1\\to S^1\\vee S^1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 代表交换子 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">[a,b]\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。约化悬挂保持带基点 CW 映射的同伦余纤维，因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≃\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmi>f\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmi>f\u003c/mi>\u003cmo>:\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>⟶\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\Sigma_r T^2\\simeq C_{\\Sigma_r f},\n\\qquad\n\\Sigma_r f:S^2\\longrightarrow S^2\\vee S^2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这里所有基点都是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-胞腔，附着给出 CW 同伦余纤维，故该性质适用。\u003c/p>\n\u003cp>交换子在一维同调中为零。由悬挂同调移位的自然性，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma_r f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在二维同调中也为零。而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">S^2\\vee S^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 单连通，Hurewicz 定理给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\pi_2(S^2\\vee S^2)\\cong H_2(S^2\\vee S^2;\\mathbb Z).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma_r f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 零伦。应用 S2 证明中的映射锥引理，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≃\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\Sigma_r T^2\\simeq S^2\\vee S^2\\vee S^3.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n另一方面，约化悬挂保持楔和，故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmi>W\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\Sigma_r W\\cong S^2\\vee S^2\\vee S^3.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n结合 (6)，得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≄\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\Sigma|L_1|\\simeq\\Sigma|L_2|,\n\\qquad |L_1|\\not\\simeq|L_2|.}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n","source":"assets/content/28ce710f6989f758d22aa3d815fe32d947e0c260d1ca8af146c8cbb205f48512.html"});
